231	    /**
232	     * Normalizes an owner's address: trims and collapses runs of whitespace to single spaces,
233	     * upper-cases the value, and expands common street-type abbreviations word-by-word
234	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or blank value
235	     * normalizes to the empty string. The normalized value is what the application stores, returns
236	     * and compares for household detection.
237	     *
238	     * @param address the raw address value from the request, may be {@code null}
239	     * @return the normalized address, or the empty string when none was supplied
240	     */
241	    private String normalizeAddress(String address) {
242	        if (address == null) {
243	            return "";
244	        }
245	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
246	        if (collapsed.isEmpty()) {
247	            return "";
248	        }
249	        String[] tokens = collapsed.split(" ");
250	        StringBuilder normalized = new StringBuilder();
251	        for (int i = 0; i < tokens.length; i++) {
252	            if (i > 0) {
253	                normalized.append(' ');
254	            }
255	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
256	        }
257	        return normalized.toString();
258	    }
259	
260	    /**
261	     * Applies address normalization to whichever address form the request supplied, preferring the
262	     * structured fields. When a non-blank {@code addressLine1} is present the structured form wins:
263	     * {@code addressLine1} (and {@code addressLine2} when present) are normalized in place, and the
264	     * flat {@code address} is set to the composed value - the normalized {@code addressLine1} with,
265	     * when an {@code addressLine2} was supplied, a single space and the normalized {@code addressLine2}
266	     * appended - so everything downstream that reads {@code address} sees the structured value. When
267	     * no {@code addressLine1} is supplied the flat {@code address} is normalized as before, keeping
268	     * earlier minimal owners backward-compatible.
269	     *
270	     * @param ownerFieldsDto the owner payload whose address fields are normalized in place
271	     */
272	    private void applyAddressFields(OwnerFieldsDto ownerFieldsDto) {
273	        if (StringUtils.hasText(ownerFieldsDto.getAddressLine1())) {
274	            String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
275	            ownerFieldsDto.setAddressLine1(line1);
276	            if (StringUtils.hasText(ownerFieldsDto.getAddressLine2())) {
277	                String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
278	                ownerFieldsDto.setAddressLine2(line2);
279	                ownerFieldsDto.setAddress(line1 + " " + line2);
280	            } else {
281	                ownerFieldsDto.setAddressLine2(null);
282	                ownerFieldsDto.setAddress(line1);
283	            }
284	        } else {
285	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
286	        }
287	    }
