318	    /**
319	     * Validates an owner's optional postcode. Postcode is optional: a {@code null} value is accepted
320	     * and leaves the owner without a postcode. When present it must be exactly 4 digits, and it must
321	     * fall within the inclusive range of the owner's city region per {@link #REGION_POSTCODE_RANGES}
322	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
323	     * region accepts any 4-digit postcode.
324	     *
325	     * @param postcode the raw postcode value from the request, may be {@code null}
326	     * @param city the owner's city, used to look up the region whose range constrains the postcode
327	     * @throws InvalidFieldsException if a supplied postcode is malformed or out of range for the city
328	     */
329	    private void validatePostcode(String postcode, String city) {
330	        if (postcode == null) {
331	            return;
332	        }
333	        if (!postcode.matches("[0-9]{4}")) {
334	            throw new InvalidFieldsException(List.of("postcode"));
335	        }
336	        String region = CITY_REGIONS.get(city);
337	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
338	        if (range != null) {
339	            int value = Integer.parseInt(postcode);
340	            if (value < range[0] || value > range[1]) {
341	                throw new InvalidFieldsException(List.of("postcode"));
342	            }
343	        }
344	    }
345	
346	    /**
347	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. A
348	     * leading '+' and its country code are kept as given; otherwise country code '+61' is assumed
349	     * and a single leading '0' is dropped from the national digits. The result must be a '+'
350	     * followed by 8 to 15 digits.
351	     *
352	     * @param telephone the raw telephone value from the request
353	     * @return the E.164 telephone (e.g. {@code +61412345678})
354	     * @throws InvalidFieldsException if the value cannot form a valid E.164 number
355	     */
356	    private String normalizeTelephone(String telephone) {
357	        if (telephone == null) {
358	            throw new InvalidFieldsException(List.of("telephone"));
359	        }
360	        String trimmed = telephone.trim();
361	        boolean international = trimmed.startsWith("+");
362	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
363	        String digits;
364	        if (international) {
365	            digits = cleaned.substring(1);
366	        } else {
367	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
368	            digits = "61" + national;
369	        }
370	        if (!digits.matches("[0-9]{8,15}")) {
371	            throw new InvalidFieldsException(List.of("telephone"));
372	        }
373	        requireValidNationalLength(digits);
374	        return "+" + digits;
375	    }
376	
377	    /**
378	     * Country codes with a fixed national-number length, checked longest-prefix first so that
379	     * '+61' is matched before the '+1' prefix it starts with. Australia ('61') requires 9 national
380	     * digits; the North American Numbering Plan ('1') requires 10.
381	     */
382	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of("61", 9, "1", 10);
383	
384	    /**
385	     * Validates that the national number (the E.164 digits after the country code) has the length
386	     * required for its country. Country codes without a known fixed length are left to the general
387	     * E.164 length check.
388	     *
389	     * @param digits the E.164 digits (country code plus national number, without the leading '+')
390	     * @throws InvalidFieldsException if the national number is the wrong length for its country
391	     */
392	    private void requireValidNationalLength(String digits) {
393	        NATIONAL_NUMBER_LENGTHS.entrySet().stream()
394	            .filter(entry -> digits.startsWith(entry.getKey()))
395	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
396	            .ifPresent(entry -> {
397	                int nationalLength = digits.length() - entry.getKey().length();
398	                if (nationalLength != entry.getValue()) {
399	                    throw new InvalidFieldsException(List.of("telephone"));
400	                }
401	            });
402	    }
403	
404	    /**
405	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
406	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
407	     * be a syntactically valid address; the accepted value is returned lower-cased.
408	     *
409	     * @param email the raw email value from the request, may be {@code null}
410	     * @return the lower-cased email, or {@code null} when none was supplied
411	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
412	     */
413	    private String normalizeEmail(String email) {
414	        if (email == null || email.isBlank()) {
415	            return null;
416	        }
417	        String trimmed = email.trim();
418	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
419	            throw new InvalidFieldsException(List.of("email"));
420	        }
421	        String normalized = trimmed.toLowerCase(Locale.ROOT);
422	        String domain = normalized.substring(normalized.indexOf('@') + 1);
423	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
424	            throw new InvalidFieldsException(List.of("email"));
425	        }
426	        return normalized;
427	    }
