451	    /**
452	     * Computes the membership level ceiling for the owner being created: one above the current
453	     * maximum membership level among the existing members of the owner's household (those sharing its
454	     * computed {@link OwnerMapper#householdId(Owner) household id}, ignoring soft-deleted owners). Each
455	     * existing member's level is evaluated for the household size that now includes the joining owner,
456	     * so the ceiling reflects the household's up-to-date standing. Returns {@code null} when the
457	     * household has no existing member, in which case no cap applies. Invoked before the new owner is
458	     * persisted, so it never counts the owner itself.
459	     *
460	     * @param owner the owner being created, with its normalized fields already applied
461	     * @return the capped maximum membership level, or {@code null} when no existing household member
462	     */
463	    private Integer householdMembershipLevelCap(Owner owner) {
464	        String householdId = ownerMapper.householdId(owner);
465	        List<Owner> members = this.clinicService.findAllOwners().stream()
466	            .filter(OwnerRestControllerV1::isNotDeleted)
467	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
468	            .toList();
469	        if (members.isEmpty()) {
470	            return null;
471	        }
472	        int householdSize = members.size() + 1;
473	        int maxLevel = members.stream()
474	            .mapToInt(existing -> ownerMapper.householdMemberLevel(existing, householdSize))
475	            .max()
476	            .getAsInt();
477	        return maxLevel + 1;
478	    }
