480	    /**
481	     * Collapses surrounding and internal whitespace and lower-cases a value so that owner household
482	     * fields can be compared case-insensitively with collapsed whitespace. A {@code null} value
483	     * normalizes to the empty string.
484	     *
485	     * @param value the raw field value, may be {@code null}
486	     * @return the trimmed, whitespace-collapsed, lower-cased form
487	     */
488	    private String normalizeHousehold(String value) {
489	        if (value == null) {
490	            return "";
491	        }
492	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
493	    }
