495	    /**
496	     * Finds an existing owner that the owner being created softly matches: one that is not a hard
497	     * duplicate (that case is already rejected by {@link #requireUniqueIdentity(Owner)}, so its
498	     * identity key differs from the new owner's) but shares the new owner's surname phonetically -
499	     * the same {@link Soundex Soundex} code for the last name - and the same postcode. Only owners
500	     * with a postcode participate: when the new owner has no postcode there is nothing to soft-match
501	     * on. When several existing owners match, the one with the lowest id is returned so the result is
502	     * deterministic.
503	     *
504	     * @param owner the owner being created, with its normalized telephone already applied
505	     * @return the lowest-id matching existing owner, or {@code null} when there is no soft match
506	     */
507	    private Owner findPossibleDuplicate(Owner owner) {
508	        String lastName = owner.getLastName();
509	        String postcode = owner.getPostcode();
510	        if (lastName == null || postcode == null) {
511	            return null;
512	        }
513	        String soundex = Soundex.encode(lastName);
514	        String identityKey = ownerMapper.identityKey(owner);
515	        return this.clinicService.findAllOwners().stream()
516	            .filter(OwnerRestControllerV1::isNotDeleted)
517	            .filter(existing -> postcode.equals(existing.getPostcode()))
518	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName())))
519	            .filter(existing -> !identityKey.equals(ownerMapper.identityKey(existing)))
520	            .min(Comparator.comparingInt(Owner::getId))
521	            .orElse(null);
522	    }
