524	    /**
525	     * Rejects an owner whose city already contains the maximum permitted number of owners
526	     * ({@value #CITY_CAPACITY}). Cities are compared case-insensitively with collapsed whitespace,
527	     * the same normalization used for the other owner household fields.
528	     *
529	     * @param city the city of the owner being created
530	     * @throws CityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more owners
531	     */
532	    private void requireCityHasCapacity(String city) {
533	        String normalizedCity = normalizeHousehold(city);
534	        long count = this.clinicService.findAllOwners().stream()
535	            .filter(existing -> normalizeHousehold(existing.getCity()).equals(normalizedCity))
536	            .count();
537	        if (count >= CITY_CAPACITY) {
538	            throw new CityAtCapacityException(city);
539	        }
540	    }
