542	    /**
543	     * Determines whether creating an owner in the given city is approaching the per-city capacity
544	     * limit: {@code true} when the city already contains between {@value #CITY_CAPACITY_WARNING_THRESHOLD}
545	     * and {@value #CITY_CAPACITY} (exclusive) owners. Cities are compared case-insensitively with
546	     * collapsed whitespace, matching {@link #requireCityHasCapacity(String)}. Evaluated before the new
547	     * owner is persisted, so the count reflects the owners that existed at the time of creation; the
548	     * hard rejection at {@value #CITY_CAPACITY} has already run, so the count seen here is below it.
549	     *
550	     * @param city the city of the owner being created
551	     * @return {@code true} when the city already holds 40-49 owners, otherwise {@code false}
552	     */
553	    private boolean isApproachingCityCapacity(String city) {
554	        String normalizedCity = normalizeHousehold(city);
555	        long count = this.clinicService.findAllOwners().stream()
556	            .filter(existing -> normalizeHousehold(existing.getCity()).equals(normalizedCity))
557	            .count();
558	        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_CAPACITY;
559	    }
