567	     * @param registrationDate the business-day-adjusted registration date of the owner being created
568	     * @throws DailyOwnerLimitException if {@value #DAILY_OWNER_LIMIT} or more owners are already
569	     *     registered on that business day
570	     */
571	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
572	        long count = this.clinicService.findAllOwners().stream()
573	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
574	            .count();
575	        if (count >= DAILY_OWNER_LIMIT) {
576	            throw new DailyOwnerLimitException(registrationDate);
