582	     * surge: {@code true} when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already
583	     * been registered on that date. Evaluated before the new owner is persisted, so the count
584	     * reflects the owners that existed at the time of creation.
585	     *
586	     * @param registrationDate the business-day-adjusted registration date of the owner being created
587	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already share
588	     *     that registration date, otherwise {@code false}
589	     */
590	    private boolean isBulkSignup(LocalDate registrationDate) {
591	        long count = this.clinicService.findAllOwners().stream()
592	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
593	            .count();
594	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
595	    }
596	
597	    /**
598	     * Rejects a supplied registration date that is later than the current server date. A {@code null}
599	     * date is permitted (it is subsequently defaulted to the server date); only an explicitly supplied
600	     * date in the future is invalid.
601	     *
602	     * @param registrationDate the registration date supplied on the request, may be {@code null}
603	     * @throws InvalidFieldsException if the supplied date is later than today's server date
604	     */
605	    private void requireRegistrationDateNotInFuture(LocalDate registrationDate) {
606	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
607	            throw new InvalidFieldsException(List.of("registrationDate"));
608	        }
609	    }
610	
611	    /**
612	     * Rolls a registration date forward onto a business day: any Saturday, Sunday or listed public
613	     * holiday is advanced day by day until the first weekday that is not a public holiday, while a
614	     * plain weekday is returned unchanged.
615	     *
616	     * @param date the effective registration date (supplied or defaulted to the server date)
617	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
618	     */
619	    private LocalDate toBusinessDay(LocalDate date) {
620	        LocalDate result = date;
621	        while (isWeekend(result) || PUBLIC_HOLIDAYS.contains(result)) {
622	            result = result.plusDays(1);
623	        }
624	        return result;
625	    }
626	
627	    private boolean isWeekend(LocalDate date) {
628	        return switch (date.getDayOfWeek()) {
629	            case SATURDAY, SUNDAY -> true;
630	            default -> false;
631	        };
632	    }
633	
634	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
635	    @Override
636	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
637	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
638	        if (StringUtils.hasText(idempotencyKey)) {
639	            Integer existingId = idempotentCreates.get(idempotencyKey);
640	            if (existingId != null) {
641	                Owner existing = this.clinicService.findOwnerById(existingId);
642	                if (existing != null) {
643	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
644	                }
645	            }
646	        }
647	        applyAddressFields(ownerFieldsDto);
648	        validateRequiredFields(ownerFieldsDto);
649	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
650	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
651	        requireCityHasCapacity(ownerFieldsDto.getCity());
652	        String email = normalizeEmail(ownerFieldsDto.getEmail());
653	        HttpHeaders headers = new HttpHeaders();
654	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
655	        owner.setTelephone(telephone);
656	        owner.setEmail(email);
657	        owner.setDeleted(false);
658	        requireUniqueIdentity(owner);
659	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
660	        requireRegistrationDateNotInFuture(owner.getRegistrationDate());
661	        LocalDate effectiveDate = owner.getRegistrationDate() != null
662	            ? owner.getRegistrationDate() : LocalDate.now();
663	        LocalDate registrationDate = toBusinessDay(effectiveDate);
664	        owner.setRegistrationDate(registrationDate);
665	        requireDailyLimitNotReached(registrationDate);
666	        owner.setBulkSignupWarning(isBulkSignup(registrationDate));
667	        owner.setCapacityWarning(isApproachingCityCapacity(ownerFieldsDto.getCity()));
668	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
669	        owner.setPossibleDuplicate(possibleDuplicate != null);
670	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
671	        owner.setMembershipLevelCap(householdMembershipLevelCap(owner));
672	        this.clinicService.saveOwner(owner);
673	        if (StringUtils.hasText(idempotencyKey)) {
674	            idempotentCreates.put(idempotencyKey, owner.getId());
675	        }
676	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
677	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
678	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
679	        AUDIT.info("{}", new OwnerCreatedEvent(AUDIT_EVENT_SEQ.incrementAndGet(), owner.getId(),
680	            primaryIdentifier(owner), ownerMapper.membershipLevel(owner)).toJson());
681	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
682	        headers.setLocation(UriComponentsBuilder.newInstance()
683	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
684	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
685	    }
686	
687	    /**
688	     * The owner's current primary identifier as carried by the structured {@code OWNER_CREATED}
689	     * audit event. Today this is the {@code customerCode}; when the customer code is later unified
690	     * into a member id, this is the single place that changes so the event automatically switches to
691	     * carrying the {@code memberId} instead.
692	     */
693	    private String primaryIdentifier(Owner owner) {
694	        return owner.getCustomerCode();
695	    }
696	
697	    /**
698	     * Immutable structured record of a successful owner creation, serialized as a single JSON object
699	     * to the {@code AUDIT} logger alongside the human-readable audit line. The {@code customerCode}
700	     * field carries the owner's current primary identifier (see {@link #primaryIdentifier(Owner)}).
701	     */
702	    private record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode,
703	                                     Integer membershipLevel) {
704	
705	        String toJson() {
706	            return "{\"seq\":" + seq
707	                + ",\"ownerId\":" + ownerId
708	                + ",\"customerCode\":" + jsonString(customerCode)
709	                + ",\"membershipLevel\":" + membershipLevel
710	                + ",\"event\":\"OWNER_CREATED\"}";
711	        }
712	
713	        private static String jsonString(String value) {
714	            if (value == null) {
715	                return "null";
716	            }
717	            StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
718	            for (int i = 0; i < value.length(); i++) {
719	                char c = value.charAt(i);
720	                switch (c) {
721	                    case '"' -> sb.append("\\\"");
722	                    case '\\' -> sb.append("\\\\");
723	                    case '\n' -> sb.append("\\n");
724	                    case '\r' -> sb.append("\\r");
725	                    case '\t' -> sb.append("\\t");
726	                    default -> {
727	                        if (c < 0x20) {
728	                            sb.append(String.format("\\u%04x", (int) c));
729	                        } else {
730	                            sb.append(c);
731	                        }
732	                    }
733	                }
734	            }
735	            return sb.append('"').toString();
736	        }
737	    }
738	
739	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
740	    @Override
741	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
742	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
743	        if (currentOwner == null) {
744	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
745	        }
746	        currentOwner.setAddress(ownerFieldsDto.getAddress());
747	        currentOwner.setCity(ownerFieldsDto.getCity());
748	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
749	        currentOwner.setLastName(ownerFieldsDto.getLastName());
750	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
751	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
752	        this.clinicService.saveOwner(currentOwner);
753	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
754	    }
755	
756	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
757	    @Transactional
758	    @Override
759	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
760	        Owner owner = this.clinicService.findOwnerById(ownerId);
761	        if (owner == null) {
762	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
763	        }
764	        owner.setDeleted(true);
765	        this.clinicService.saveOwner(owner);
766	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
767	    }
768	
769	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
770	    @Override
771	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
772	        Owner owner = this.clinicService.findOwnerById(ownerId);
773	        if (owner == null) {
774	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
775	        }
776	        HttpHeaders headers = new HttpHeaders();
777	        Pet pet = petMapper.toPet(petFieldsDto);
778	        owner.setId(ownerId);
779	        pet.setOwner(owner);
780	        pet.getType().setName(null);
781	        this.clinicService.savePet(pet);
782	        PetDto petDto = petMapper.toPetDto(pet);
783	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
784	            .buildAndExpand(pet.getId()).toUri());
785	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
786	    }
787	
788	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
789	    @Override
790	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
791	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
792	        if (currentOwner != null) {
793	            Pet currentPet = this.clinicService.findPetById(petId);
794	            if (currentPet != null) {
795	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
796	                currentPet.setName(petFieldsDto.getName());
797	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
798	                this.clinicService.savePet(currentPet);
799	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
800	            }
801	        }
802	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
803	    }
804	
805	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
806	    @Override
807	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
808	        HttpHeaders headers = new HttpHeaders();
809	        Visit visit = visitMapper.toVisit(visitFieldsDto);
810	        Pet pet = new Pet();
811	        pet.setId(petId);
812	        visit.setPet(pet);
813	        this.clinicService.saveVisit(visit);
814	        VisitDto visitDto = visitMapper.toVisitDto(visit);
815	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
816	            .buildAndExpand(visit.getId()).toUri());
817	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
818	    }
819	
820	
821	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
822	    @Override
823	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
824	        Owner owner = this.clinicService.findOwnerById(ownerId);
825	        if (owner != null) {
826	            Pet pet = owner.getPet(petId);
827	            if (pet != null) {
828	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
