82	     *
83	     * @param owner the owner to derive the age band for
84	     * @return {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"}, or {@code null} when no birth date
85	     *     is held
86	     */
87	    default String ageBand(Owner owner) {
88	        java.time.LocalDate birthDate = owner.getBirthDate();
89	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
90	        if (birthDate == null || registrationDate == null) {
91	            return null;
92	        }
93	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
94	        if (age < 18) {
95	            return "MINOR";
96	        }
97	        return age < 65 ? "ADULT" : "SENIOR";
98	    }
99	
100	    /**
101	     * Derives an owner's preferred contact channel: {@code "EMAIL"} when the owner has a non-blank
102	     * email, otherwise {@code "PHONE"}.
103	     *
104	     * @param owner the owner to derive the contact preference for
105	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
106	     */
107	    default String contactPreference(Owner owner) {
108	        String email = owner.getEmail();
109	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
110	    }
111	
112	    /**
113	     * Known telephone country codes, matched longest-prefix first so {@code "61"} is preferred over
114	     * the {@code "1"} it starts with. Mirrors the country codes the create endpoint recognizes when
115	     * normalizing telephones into E.164 form.
116	     */
117	    java.util.List<String> TELEPHONE_COUNTRY_CODES = java.util.List.of("61", "1");
118	
119	    /**
120	     * Formats an owner's stored E.164 telephone for humans: the country code, a space, then the
121	     * national digits grouped in threes (e.g. {@code +61412345678} becomes {@code +61 412 345 678}).
122	     * The country code is taken as the longest recognized prefix (see
123	     * {@link #TELEPHONE_COUNTRY_CODES}), falling back to the leading digit; the raw
124	     * {@link Owner#getTelephone() telephone} stays in E.164 form. A {@code null} or non-E.164 value
125	     * is returned unchanged.
126	     *
127	     * @param owner the owner to format the telephone display for
128	     * @return the human-formatted telephone, or the raw value when it is not a {@code +}-prefixed
129	     *     digit string
130	     */
131	    default String telephoneDisplay(Owner owner) {
132	        String telephone = owner.getTelephone();
133	        if (telephone == null || !telephone.startsWith("+")) {
134	            return telephone;
135	        }
136	        String digits = telephone.substring(1);
137	        if (!digits.matches("[0-9]+")) {
138	            return telephone;
139	        }
140	        String countryCode = TELEPHONE_COUNTRY_CODES.stream()
141	            .filter(digits::startsWith)
142	            .max(java.util.Comparator.comparingInt(String::length))
143	            .orElseGet(() -> digits.substring(0, 1));
144	        String national = digits.substring(countryCode.length());
145	        StringBuilder sb = new StringBuilder("+").append(countryCode);
146	        for (int i = 0; i < national.length(); i += 3) {
147	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
148	        }
149	        return sb.toString();
150	    }
151	
152	    /**
153	     * Derives an owner's locality from the region-and-hash customer code: the {@code <REGION>}
154	     * segment (everything before the first {@code '-'}) of the owner's {@code customerCode}. Because
155	     * the customer code's region is itself derived from the postcode (falling back to the city), the
156	     * locality now moves with the identity rather than being computed independently. The result is
157	     * {@code "UNKNOWN"} when no customer code is present.
158	     *
159	     * @param owner the owner to derive the locality for
160	     * @return the region segment of the customer code, or {@code "UNKNOWN"}
161	     */
162	    default String locality(Owner owner) {
163	        String code = owner.getCustomerCode();
164	        if (code == null || code.isEmpty()) {
165	            return "UNKNOWN";
166	        }
167	        int dash = code.indexOf('-');
168	        return dash < 0 ? code : code.substring(0, dash);
169	    }
170	
171	    /**
172	     * Fixed region-to-timezone table mapping a canonical region to its IANA timezone name:
173	     * {@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}.
174	     */
175	    java.util.Map<String, String> REGION_TIMEZONES = java.util.Map.of(
176	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
177	
178	    /**
179	     * The regions considered {@code METRO} for the purposes of {@link #ownerSegment(Owner)}: the
180	     * known regions {@code NSW}, {@code VIC} and {@code QLD}. Any other locality is {@code REGIONAL}.
181	     */
182	    java.util.Set<String> METRO_REGIONS = java.util.Set.of("NSW", "VIC", "QLD");
183	
184	    /**
185	     * Derives an owner's segment, formatted {@code <TIER>_<AREA>}. {@code TIER} is {@code PREMIUM}
186	     * when the owner's {@link #membershipLevel(Owner) membership level} is {@code 3} or more,
187	     * otherwise {@code STANDARD}. {@code AREA} is {@code METRO} when the owner's
188	     * {@link #locality(Owner) locality} is a known region ({@code NSW}, {@code VIC} or {@code QLD}),
189	     * otherwise {@code REGIONAL}. The result is one of {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL},
190	     * {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}.
191	     *
192	     * @param owner the owner to derive the segment for
193	     * @return the {@code <TIER>_<AREA>} owner segment
194	     */
195	    default String ownerSegment(Owner owner) {
196	        String tier = membershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
197	        String area = METRO_REGIONS.contains(locality(owner)) ? "METRO" : "REGIONAL";
198	        return tier + "_" + area;
199	    }
200	
201	    /**
202	     * Derives an owner's IANA timezone name from its {@link #locality(Owner) locality/region} using
203	     * the fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
204	     * {@code QLD->Australia/Brisbane}). Returns {@code null} when the region has no known timezone, so
205	     * the field is omitted from the response.
206	     *
207	     * @param owner the owner to derive the timezone for
208	     * @return the region's IANA timezone name, or {@code null} when the region has no known timezone
209	     */
210	    default String timezone(Owner owner) {
211	        return REGION_TIMEZONES.get(locality(owner));
212	    }
213	
214	    /**
215	     * Derives an owner's membership points. Starts at {@code 0}, plus {@code 2} when an email is
216	     * present (non-blank), plus {@code 1} when the owner's namesake count is {@code 0}, plus
217	     * {@code 2} for a household of {@code 3} or more members, plus {@code 3} for a tenure of more
218	     * than one elapsed fiscal year - the number of fiscal years between the owner's registration
219	     * date and the current server date (the fiscal year starts on 1 July). Because a newly created
220	     * owner registers on the current date, its tenure is zero, so a new owner never earns the tenure
221	     * points.
222	     *
223	     * @param owner the owner to derive the membership points for
224	     * @return the membership points, {@code 0} or more
225	     */
226	    default Integer membershipPoints(Owner owner) {
227	        return membershipPoints(owner, owner.getHouseholdMemberCount());
228	    }
229	
230	    /**
231	     * Derives an owner's membership points as {@link #membershipPoints(Owner)}, but scoring the
232	     * household bonus against the supplied household member count rather than the owner's stored one.
233	     * Used to evaluate an existing household member's current standing against the household size that
234	     * includes a newly joining owner.
235	     *
236	     * @param owner the owner to derive the membership points for
237	     * @param householdMemberCount the household member count to score the household bonus against
238	     * @return the membership points, {@code 0} or more
239	     */
240	    private int membershipPoints(Owner owner, Integer householdMemberCount) {
241	        int points = 0;
242	        String email = owner.getEmail();
243	        if (email != null && !email.isBlank()) {
244	            points += 2;
245	        }
246	        Integer namesakeCount = owner.getNamesakeCount();
247	        if (namesakeCount != null && namesakeCount == 0) {
248	            points += 1;
249	        }
250	        if (householdMemberCount != null && householdMemberCount >= 3) {
251	            points += 2;
252	        }
253	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
254	        long tenureFiscalYears = registrationDate == null ? 0
255	            : fiscalYearValue(java.time.LocalDate.now()) - fiscalYearValue(registrationDate);
256	        if (tenureFiscalYears > 1) {
257	            points += 3;
258	        }
259	        return points;
260	    }
261	
262	    /**
263	     * Derives an owner's numeric membership level from its {@link #membershipPoints(Owner) membership
264	     * points}: level {@code 1} for {@code 0}-{@code 1} points, {@code 2} for {@code 2}-{@code 3},
265	     * {@code 3} for {@code 4}-{@code 5}, and {@code 4} for {@code 6} or more. The points-derived
266	     * level is then capped by the owner's {@link Owner#getMembershipLevelCap() membership level cap}
267	     * when one was recorded at creation - a new owner's level can never exceed one above the highest
268	     * level among the household members that already existed. When no cap was recorded (the owner had
269	     * no existing household member) the points-derived level is returned unchanged.
270	     *
271	     * @param owner the owner to derive the membership level for
272	     * @return the membership level, between {@code 1} and {@code 4}
273	     */
274	    default Integer membershipLevel(Owner owner) {
275	        return cappedLevel(owner, levelForPoints(membershipPoints(owner)));
276	    }
277	
278	    /**
279	     * Derives an existing household member's current membership level as it would stand in a household
280	     * of the supplied size, so a newly joining owner's level ceiling can be measured against the
281	     * up-to-date standing of the members it joins. The member's own {@link Owner#getMembershipLevelCap()
282	     * cap} still applies.
283	     *
284	     * @param owner the existing household member to evaluate
285	     * @param householdMemberCount the household member count that includes the joining owner
286	     * @return the member's capped membership level for that household size, between {@code 1} and {@code 4}
287	     */
288	    default Integer householdMemberLevel(Owner owner, int householdMemberCount) {
289	        return cappedLevel(owner, levelForPoints(membershipPoints(owner, householdMemberCount)));
290	    }
291	
292	    /**
293	     * Applies an owner's {@link Owner#getMembershipLevelCap() membership level cap} to a points-derived
294	     * level: the level is returned unchanged when no cap was recorded, otherwise it is clamped to the
295	     * cap.
296	     *
297	     * @param owner the owner whose cap is applied
298	     * @param level the uncapped points-derived level
299	     * @return the capped level
300	     */
301	    private Integer cappedLevel(Owner owner, int level) {
302	        Integer cap = owner.getMembershipLevelCap();
303	        if (cap != null && level > cap) {
304	            return cap;
305	        }
306	        return level;
307	    }
308	
309	    /**
310	     * Maps membership points to a numeric level: level {@code 1} for {@code 0}-{@code 1} points,
311	     * {@code 2} for {@code 2}-{@code 3}, {@code 3} for {@code 4}-{@code 5}, and {@code 4} for
312	     * {@code 6} or more.
313	     *
314	     * @param points the membership points
315	     * @return the points-based membership level, between {@code 1} and {@code 4}
316	     */
317	    private Integer levelForPoints(int points) {
318	        if (points <= 1) {
319	            return 1;
320	        }
321	        if (points <= 3) {
322	            return 2;
323	        }
324	        if (points <= 5) {
325	            return 3;
326	        }
327	        return 4;
328	    }
329	
330	    /**
331	     * Derives an owner's membership number, formatted {@code <customerCode>-M<YY>} where
332	     * {@code <customerCode>} is the owner's region-and-hash customer code and {@code YY} is the last
333	     * two digits (zero-padded) of the owner's {@link #fiscalYear(Owner) fiscal year} - so the year
334	     * segment matches the returned {@code fiscalYear} (e.g. {@code NSW-1A2B3C4D-M27}).
335	     *
336	     * @param owner the owner to derive the membership number for
337	     * @return the formatted membership number
338	     */
339	    default String membershipNumber(Owner owner) {
340	        String yy = String.format("%02d", fiscalYearValue(owner.getRegistrationDate()) % 100);
341	        return owner.getCustomerCode() + "-M" + yy;
342	    }
343	
344	    /**
345	     * Derives an owner's fiscal year, formatted {@code FY<YY>} where {@code YY} is the last two
346	     * digits (zero-padded) of the fiscal year that the owner's business-day-adjusted registration
347	     * date falls in. The fiscal year starts on 1 July and is labelled by the calendar year in which
348	     * it ends, so a registration date on or after 1 July belongs to the next year's fiscal year
349	     * (e.g. {@code 2026-08-11 -> FY27}, {@code 2026-01-05 -> FY26}).
350	     *
351	     * @param owner the owner to derive the fiscal year for
352	     * @return the formatted fiscal year
353	     */
354	    default String fiscalYear(Owner owner) {
355	        return String.format("FY%02d", fiscalYearValue(owner.getRegistrationDate()) % 100);
356	    }
357	
358	    /**
359	     * Computes the fiscal year a date falls in as a full four-digit year. The fiscal year starts on
360	     * 1 July and is labelled by the calendar year in which it ends, so a date in July through
361	     * December belongs to the following calendar year's fiscal year and a date in January through
362	     * June belongs to its own calendar year's fiscal year.
363	     *
364	     * @param date the date to compute the fiscal year for
365	     * @return the fiscal year as a four-digit calendar year
366	     */
367	    private int fiscalYearValue(java.time.LocalDate date) {
368	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
369	    }
370	
371	    /**
372	     * Derives an owner's check digit: a single Luhn check digit ({@code 0}-{@code 9}) computed over
373	     * the digits contained in the owner's customer code. Non-digit characters in the customer code
374	     * are ignored.
375	     *
376	     * @param owner the owner to derive the check digit for
377	     * @return the Luhn check digit, between {@code 0} and {@code 9}
378	     */
379	    default Integer checkDigit(Owner owner) {
380	        String code = owner.getCustomerCode();
381	        int sum = 0;
382	        boolean dbl = true;
383	        for (int i = code.length() - 1; i >= 0; i--) {
384	            char c = code.charAt(i);
385	            if (c < '0' || c > '9') {
386	                continue;
387	            }
388	            int d = c - '0';
389	            if (dbl) {
390	                d *= 2;
391	                if (d > 9) {
392	                    d -= 9;
393	                }
394	            }
395	            sum += d;
396	            dbl = !dbl;
397	        }
398	        return (10 - (sum % 10)) % 10;
399	    }
400	
401	    /**
402	     * Derives an owner's household identifier: the first 12 hex characters of the SHA-256 digest
403	     * over {@code <normalizedLastName>|<postcode>}, where the last name is normalized
404	     * case-insensitively with collapsed whitespace and a missing postcode contributes the empty
405	     * string. Because it is derived deterministically from the last name and postcode, every owner
406	     * that shares those two fields receives the same value - including owners created via the
407	     * {@code sharesHousehold} flag, which by definition have a matching last name and postcode.
408	     *
409	     * @param owner the owner to derive the household identifier for
410	     * @return the 12 upper-case hex character household identifier, never blank
411	     */
412	    default String householdId(Owner owner) {
413	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
414	        String key = normalizeHouseholdField(owner.getLastName()) + '|' + postcode;
415	        try {
416	            byte[] digest = MessageDigest.getInstance("SHA-256")
417	                .digest(key.getBytes(StandardCharsets.UTF_8));
418	            StringBuilder sb = new StringBuilder(12);
419	            for (int i = 0; i < 6; i++) {
420	                sb.append(String.format("%02X", digest[i]));
421	            }
422	            return sb.toString();
423	        }
424	        catch (NoSuchAlgorithmException ex) {
425	            throw new IllegalStateException("SHA-256 not available", ex);
426	        }
427	    }
428	
429	    /**
430	     * Derives an owner's identity key, into which all duplicate detection is consolidated. The key
431	     * is the full lower-case hex SHA-256 digest over
432	     * {@code <normalizedTelephone>|<email or empty>|<soundex(lastName)>}: the owner's (already E.164
433	     * normalized) telephone, its (already lower-cased) email or the empty string when none is held,
434	     * and the {@link Soundex Soundex} code of its last name. Two owners are duplicates only when
435	     * their whole identity keys are equal; because the telephone is part of the key, owners sharing a
436	     * surname (same soundex) but holding different telephones have different keys.
437	     *
438	     * @param owner the owner to derive the identity key for
439	     * @return the 64-character lower-case hex identity key
440	     */
441	    default String identityKey(Owner owner) {
442	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
443	        String email = owner.getEmail() == null ? "" : owner.getEmail();
444	        String key = telephone + '|' + email + '|' + Soundex.encode(owner.getLastName());
445	        try {
446	            byte[] digest = MessageDigest.getInstance("SHA-256")
447	                .digest(key.getBytes(StandardCharsets.UTF_8));
448	            StringBuilder sb = new StringBuilder(digest.length * 2);
449	            for (byte b : digest) {
450	                sb.append(String.format("%02x", b));
451	            }
452	            return sb.toString();
453	        }
454	        catch (NoSuchAlgorithmException ex) {
455	            throw new IllegalStateException("SHA-256 not available", ex);
456	        }
457	    }
458	
459	    /**
460	     * Collapses surrounding and internal whitespace and lower-cases a value so household fields can
461	     * be compared case-insensitively with collapsed whitespace. A {@code null} value normalizes to
462	     * the empty string. Mirrors the normalization used when enforcing the household rule on create.
463	     *
464	     * <p>Declared {@code private} so MapStruct does not treat it as an implicit String-to-String
465	     * conversion and apply it to unrelated String properties (last name, address, ...).
466	     */
467	    private String normalizeHouseholdField(String value) {
468	        if (value == null) {
469	            return "";
470	        }
471	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
472	    }
473	
474	    Owner toOwner(OwnerDto ownerDto);
475	
476	    @Mapping(target = "id", ignore = true)
477	    @Mapping(target = "pets", ignore = true)
478	    Owner toOwner(OwnerFieldsDto ownerDto);
479	
480	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
481	
482	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
483	
484	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
485	        OwnerPageDto ownerPageDto = new OwnerPageDto();
486	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
487	        ownerPageDto.setPage(ownerPage.getNumber());
488	        ownerPageDto.setSize(ownerPage.getSize());
489	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
490	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
491	        return ownerPageDto;
492	    }
493	}
